function normalizarNomeIntegrante(nome: string) {
  return nome
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/^(pr|pra|apa)\.?\s+/i, '')
    .trim()
    .toLowerCase();
}

function obterChaveIntegrante(nome: string) {
  const nomeNormalizado = normalizarNomeIntegrante(nome);
  return NOMES_USUARIOS.find(usuario => normalizarNomeIntegrante(usuario) === nomeNormalizado);
}

function obterUidPorNomeIntegrante(nome: string) {
  const nomeNormalizado = normalizarNomeIntegrante(nome);
  return Object.entries(UID_TO_NOME).find(([, nomeUsuario]) => (
    normalizarNomeIntegrante(nomeUsuario) === nomeNormalizado
  ))?.[0];
}

function corrigirNomeIntegrante(nome: string) {
  const nomesCorrigidos: Record<string, string> = {
    sheila: 'Scheila',
    mirian: 'Miriam',
  };

  const nomeNormalizado = normalizarNomeIntegrante(nome);
  return nomesCorrigidos[nomeNormalizado] || obterChaveIntegrante(nome) || nome;
}

function corrigirNomesEscala(dados: any) {
  if (!dados || typeof dados !== 'object') return dados;

  return Object.entries(dados).reduce((acc, [campo, valor]) => {
    acc[campo] = CAMPOS_INTEGRANTES.has(campo) && typeof valor === 'string'
      ? corrigirNomeIntegrante(valor)
      : valor;
    return acc;
  }, {} as any);
}

function escalaTemNomeCorrigido(original: any, corrigida: any) {
  return JSON.stringify(original) !== JSON.stringify(corrigida);
}

