export default function TelaDetalhesEscala(): JSX.Element {
  const route = useRoute<RotaDetalhesEscala>();
  const navigation = useNavigation();
  const id = route.params?.id;

  const [escala, setEscala] = useState<any>(null);
  const [loading, setLoading] = useState(true);
  const [uidAtual, setUidAtual] = useState<string | null>(null);
  const [editando, setEditando] = useState(false);
  const [escalaEdit, setEscalaEdit] = useState<any>({});
  const [fotosIntegrantes, setFotosIntegrantes] = useState<Record<string, string>>(FOTOS_PADRAO);

  // Animação de alto relevo para os botões
  const animBtn1 = React.useRef(new Animated.Value(1)).current;
  const animBtn2 = React.useRef(new Animated.Value(1)).current;

  // Animação de chamada de atenção para o botão de confirmação de presença
  const pulseConfirmacao = React.useRef(new Animated.Value(1)).current;

  useEffect(() => {
    const nomeUsuarioAtual = uidAtual ? UID_TO_NOME[uidAtual] : undefined;
    const nomeAtualNormalizado = nomeUsuarioAtual ? normalizarNomeIntegrante(nomeUsuarioAtual) : '';
    const usuarioEscaladoAgora = !!nomeAtualNormalizado && Array.from(CAMPOS_INTEGRANTES).some((campo) => {
      const valor = escala?.[campo];
      return typeof valor === 'string' && normalizarNomeIntegrante(valor) === nomeAtualNormalizado;
    });
    const presencaConfirmadaAgora = !!uidAtual && !!escala?.confirmacoesPresenca?.[uidAtual];

    if (usuarioEscaladoAgora && !presencaConfirmadaAgora) {
      const loop = Animated.loop(
        Animated.sequence([
          Animated.timing(pulseConfirmacao, { toValue: 1.04, duration: 650, useNativeDriver: true }),
          Animated.timing(pulseConfirmacao, { toValue: 1, duration: 650, useNativeDriver: true }),
        ])
      );
      loop.start();
      return () => loop.stop();
    }
    pulseConfirmacao.setValue(1);
  }, [uidAtual, escala]);

  useEffect(() => {
    setUidAtual(auth.currentUser?.uid ?? null);

    if (!id) return;
    const carregarEscala = async () => {
      try {
        const docSnap = await getDoc(doc(db, 'escalas', id));
        if (docSnap.exists()) {
          const dadosEscala = docSnap.data();
          const dadosCorrigidos = corrigirNomesEscala(dadosEscala);
          setEscala(dadosCorrigidos);
          setEscalaEdit(dadosCorrigidos);
          if (escalaTemNomeCorrigido(dadosEscala, dadosCorrigidos)) {
            await updateDoc(doc(db, 'escalas', id), dadosCorrigidos);
          }
        } else {
          setEscala(null);
        }
      } catch (e) {
        setEscala(null);
      } finally {
        setLoading(false);
      }
    };
    carregarEscala();
  }, [id]);

  useEffect(() => {
    let fotosLocal: Record<string, string> = {};

    AsyncStorage.getItem('fotosUsuarios')
      .then(valor => {
        if (valor) fotosLocal = JSON.parse(valor);
      })
      .catch(() => {});

    const unsubscribe = onSnapshot(collection(db, 'presencas'), snapshot => {
      const fotosBanco: Record<string, string> = {};
      snapshot.docs.forEach(docSnap => {
        Object.entries(docSnap.data().fotosUsuarios || {}).forEach(([nome, foto]) => {
          if (typeof foto === 'string' && foto) {
            fotosBanco[nome] = foto;
          }
        });
      });

      const fotosAtuais = { ...FOTOS_PADRAO, ...fotosBanco, ...fotosLocal };
      const fotosFiltradas = NOMES_USUARIOS.reduce((acc, nome) => {
        acc[nome] = fotosAtuais[nome] || `https://ui-avatars.com/api/?name=${encodeURIComponent(nome)}`;
        return acc;
      }, {} as Record<string, string>);
      setFotosIntegrantes(fotosFiltradas);
    }, error => {
      console.log('Erro ao carregar fotos da presenca:', error);
    });

    return () => unsubscribe();
  }, []);

  // Máscara automÃ¡tica para data dd/mm/aaaa
  const handleChange = (campo: string, valor: string) => {
    if (campo === 'data') {
      let cleaned = valor.replace(/\D/g, '');
      if (cleaned.length > 8) cleaned = cleaned.slice(0, 8);
      let formatted = cleaned;
      if (cleaned.length > 4) {
        formatted = `${cleaned.slice(0, 2)}/${cleaned.slice(2, 4)}/${cleaned.slice(4)}`;
      } else if (cleaned.length > 2) {
        formatted = `${cleaned.slice(0, 2)}/${cleaned.slice(2)}`;
      }
      setEscalaEdit((prev: any) => ({ ...prev, [campo]: formatted }));
    } else {
      setEscalaEdit((prev: any) => ({ ...prev, [campo]: valor }));
    }
  };

  const salvarAlterações = async () => {
    if (!id) {
      Alert.alert('Erro', 'ID da escala não informado.');
      return;
    }
    try {
      await updateDoc(doc(db, 'escalas', id), {
        ...escalaEdit,
        atualizadoEm: serverTimestamp(),
      });
      if (escalaEdit.uniforme?.corCamiseta && escalaEdit.uniforme?.corCalcaSaia) {
        await setDoc(doc(db, 'meta', 'uniformeCulto'), {
          corCamiseta: escalaEdit.uniforme.corCamiseta,
          corCalcaSaia: escalaEdit.uniforme.corCalcaSaia,
          atualizadoEm: new Date(),
          atualizadoPor: uidAtual,
          origem: 'escala',
          escalaId: id,
        }, { merge: true });
      }
      setEscala({ ...escalaEdit });
      setEditando(false);
      Alert.alert('Sucesso', 'Escala atualizada com sucesso!');
      // incrementa contador remoto e local para sinalizar atualização
      const metaRef = doc(db, 'meta', 'escalas');
      try {
        await updateDoc(metaRef, { newCount: increment(1), lastUpdated: new Date() });
      } catch (err) {
        try {
          await setDoc(metaRef, { newCount: 1, lastUpdated: new Date() }, { merge: true });
        } catch (e2) {
          console.log('Erro ao incrementar contador remoto após editar escala', e2);
        }
      }
      try {
        const cur = await AsyncStorage.getItem('nova_escala');
        const num = cur ? parseInt(cur, 10) || 0 : 0;
        const novo = num + 1;
        await AsyncStorage.setItem('nova_escala', String(novo));
        await Notifications.setBadgeCountAsync(novo);
      } catch (e) {
        console.log('Erro ao setar contador/badge local depois de editar escala', e);
      }
    } catch (error) {
      Alert.alert('Erro', 'Não foi possível salvar as alterações.');
    }
  };

  const confirmarExclusao = async () => {
    if (!id) {
      Alert.alert('Erro', 'ID da escala não informado.');
      return;
    }
    confirmAction({
      title: 'Excluir Escala',
      message: `Deseja realmente excluir a escala "${escala?.data || escalaEdit?.data || id}"? Esta ação não pode ser desfeita.`,
      onConfirm: async () => {
        try {
          await deleteDoc(doc(db, 'escalas', id));
          Alert.alert('Sucesso', 'Escala excluída com sucesso!');
          // @ts-ignore
          if (navigation && navigation.goBack) navigation.goBack();
        } catch (error) {
          Alert.alert('Erro', 'Não foi possível excluir a escala.');
        }
      },
    });
  };

  const obterFuncoesDoUsuarioNaEscala = () => {
    if (!uidAtual) return [];

    const nomeUsuarioAtual = UID_TO_NOME[uidAtual];
    if (!nomeUsuarioAtual) return [];

    const nomeAtualNormalizado = normalizarNomeIntegrante(nomeUsuarioAtual);
    return Array.from(CAMPOS_INTEGRANTES)
      .filter(campo => {
        const valor = escala?.[campo];
        return typeof valor === 'string' && normalizarNomeIntegrante(valor) === nomeAtualNormalizado;
      })
      .map(labelComAcento);
  };

  const confirmarPresenca = async () => {
    if (!id || !uidAtual) {
      Alert.alert('Atenção', 'Entre novamente na sua conta para confirmar presença.');
      return;
    }

    const nomeUsuarioAtual = UID_TO_NOME[uidAtual];
    const funcoes = obterFuncoesDoUsuarioNaEscala();
    if (!nomeUsuarioAtual || funcoes.length === 0) {
      Alert.alert('Escala', 'Seu usuário não aparece nesta escala.');
      return;
    }

    try {
      const confirmacao = {
        uid: uidAtual,
        nome: nomeUsuarioAtual,
        funcoes,
        confirmadoEm: new Date(),
      };
      await updateDoc(doc(db, 'escalas', id), {
        [`confirmacoesPresenca.${uidAtual}`]: confirmacao,
      });
      setEscala((prev: any) => ({
        ...prev,
        confirmacoesPresenca: {
          ...(prev?.confirmacoesPresenca || {}),
          [uidAtual]: confirmacao,
        },
      }));
      setEscalaEdit((prev: any) => ({
        ...prev,
        confirmacoesPresenca: {
          ...(prev?.confirmacoesPresenca || {}),
          [uidAtual]: confirmacao,
        },
      }));
      Alert.alert('Presença confirmada', 'Sua presença foi confirmada nesta escala.');
    } catch (error) {
      Alert.alert('Erro', 'Não foi possível confirmar sua presença.');
    }
  };

  const alterarCorUniforme = (campo: 'corCamiseta' | 'corCalcaSaia', cor: string) => {
    setEscalaEdit((prev: any) => ({
      ...prev,
      uniforme: {
        ...UNIFORME_PADRAO,
        ...(prev.uniforme || {}),
        [campo]: cor,
      },
    }));
  };

  const obterFotoIntegrante = (nome: string) => {
    if (!nome?.trim()) return null;

    const chaveIntegrante = obterChaveIntegrante(nome);
    return (chaveIntegrante && fotosIntegrantes[chaveIntegrante])
      || fotosIntegrantes[nome]
      || `https://ui-avatars.com/api/?name=${encodeURIComponent(nome)}`;
  };

  if (!id) {
    return (
      <View style={styles.bg}>
        <View style={styles.loadingContainer}>
          <Text>ID da escala não informado.</Text>
        </View>
      </View>
    );
  }

  if (loading) {
    return (
      <View style={styles.bg}>
        <View style={styles.loadingContainer}>
          <ActivityIndicator size="large" color="#ff9800" />
        </View>
      </View>
    );
  }

  if (!escala) {
    return (
      <View style={styles.bg}>
        <View style={styles.loadingContainer}>
          <Text>Escala não encontrada.</Text>
        </View>
      </View>
    );
  }

  const camposOrdenados = [
    ...ordemCampos.filter((campo) => escala[campo] !== undefined && campo !== 'uniforme' && campo !== 'confirmacoesPresenca'),
    ...Object.keys(escala).filter((campo) => !ordemCampos.includes(campo) && campo !== 'uniforme' && campo !== 'confirmacoesPresenca'),
  ];

  const permitido = !!uidAtual && UIDS_PERMITIDOS.includes(uidAtual);
  const funcoesUsuarioNaEscala = obterFuncoesDoUsuarioNaEscala();
  const usuarioEstaEscalado = funcoesUsuarioNaEscala.length > 0;
  const presencaConfirmada = !!uidAtual && !!escala?.confirmacoesPresenca?.[uidAtual];

  // Efeito de alto relevo nos botões
  const handlePressIn = (anim: Animated.Value) => {
    Animated.spring(anim, {
      toValue: 0.96,
      useNativeDriver: true,
    }).start();
  };
  const handlePressOut = (anim: Animated.Value) => {
    Animated.spring(anim, {
      toValue: 1,
      friction: 3,
      tension: 40,
      useNativeDriver: true,
    }).start();
  };

  return (
    <LinearGradient colors={['#0B1630', '#151936', '#241A3D']} style={styles.bg}>
      {/* HEADER NEUMÓRFICO PERSONALIZADO */}
      <View style={styles.headerNeumorphic}>
        <LinearGradient
          colors={['#262A50', '#1B1F3D']}
          start={{ x: 0, y: 0 }}
          end={{ x: 1, y: 1 }}
          style={styles.headerRow}
        >
          {/* Botão Home à esquerda */}
          <TouchableOpacity
            style={styles.headerIconBtn}
            onPress={() => navigation.navigate('Inicio')}
            activeOpacity={0.7}
          >
            <MaterialCommunityIcons name="home-variant-outline" size={24} color="#43E97B" />
          </TouchableOpacity>

          {/* Título centralizado */}
          <View style={styles.headerCenterBox}>
            <Text style={styles.novaEscalaText}>Detalhes da Escala</Text>
          </View>

          {/* Botão Voltar à direita */}
          <TouchableOpacity
            style={styles.headerIconBtn}
            onPress={() => navigation.goBack()}
            activeOpacity={0.7}
          >
            <MaterialIcons name="keyboard-backspace" size={25} color="#46D7FF" />
          </TouchableOpacity>
        </LinearGradient>
      </View>
      {/* FIM HEADER */}

      <ScrollView contentContainerStyle={styles.container}>
        <View style={styles.card}>
          {usuarioEstaEscalado && (
            <Animated.View style={{ transform: [{ scale: pulseConfirmacao }] }}>
              <NeumorphicContainer
                style={styles.confirmacaoPresencaBox}
                borderColors={['#FFB84D', '#43E97B', '#46D7FF']}
                innerColors={['#151C3C', '#222047']}
                borderWidth={1.3}
              >
                <View style={styles.confirmacaoHeader}>
                  <View style={styles.confirmacaoIconCircle}>
                    <MaterialIcons name={presencaConfirmada ? 'check-circle' : 'how-to-reg'} size={24} color="#111827" />
                  </View>
                  <View style={styles.confirmacaoTextoBox}>
                    <Text style={styles.confirmacaoTitulo}>
                      {presencaConfirmada ? 'Presença confirmada' : 'Confirmar presença'}
                    </Text>
                    <Text style={styles.confirmacaoSubtitulo} numberOfLines={2}>
                      Você está escalado em {funcoesUsuarioNaEscala.join(', ')}.
                    </Text>
                  </View>
                </View>
                <TouchableOpacity
                  style={[styles.confirmacaoBotao, presencaConfirmada && styles.confirmacaoBotaoConfirmado]}
                  onPress={confirmarPresenca}
                  activeOpacity={0.85}
                >
                  <MaterialIcons name={presencaConfirmada ? 'done-all' : 'check'} size={20} color="#111827" />
                  <Text style={styles.confirmacaoBotaoTexto}>
                    {presencaConfirmada ? 'Confirmado' : 'Estou presente'}
                  </Text>
                </TouchableOpacity>
              </NeumorphicContainer>
            </Animated.View>
          )}

          {camposOrdenados.map((campo) => {
            const valorCampo = campo === 'criadoEm' || campo === 'criadoem'
              ? formatarData(escala[campo])
              : CAMPOS_INTEGRANTES.has(campo)
                ? corrigirNomeIntegrante(String(escala[campo]))
                : String(escala[campo]);
            const fotoIntegrante = CAMPOS_INTEGRANTES.has(campo) ? obterFotoIntegrante(valorCampo) : null;
            const uidIntegrante = CAMPOS_INTEGRANTES.has(campo) ? obterUidPorNomeIntegrante(valorCampo) : undefined;
            const integranteTemNome = CAMPOS_INTEGRANTES.has(campo) && valorCampo.trim().length > 0;
            const integranteConfirmou = !!uidIntegrante && !!escala?.confirmacoesPresenca?.[uidIntegrante];

            return (
              <NeumorphicContainer key={campo} style={styles.inputGroup}>
                <View style={styles.fieldRow}>
                  <View style={styles.fieldIconCircle}>
                    <MaterialCommunityIcons name={nomeIconeCampo(campo)} size={22} color="#111827" />
                  </View>
                  <Text style={styles.label} numberOfLines={1}>{labelComAcento(campo)}</Text>
                  {!editando || campo === 'criadoEm' ? (
                    <View
                      style={[
                        styles.valorBox,
                        fotoIntegrante && styles.valorBoxIntegrante,
                        integranteConfirmou && styles.valorBoxConfirmado,
                      ]}
                    >
                      {fotoIntegrante ? (
                        <>
                          <View style={styles.valorIntegranteRow}>
                            <Image source={{ uri: fotoIntegrante }} style={styles.valorIntegranteFoto} />
                            <Text style={[styles.valor, styles.valorIntegranteNome]} numberOfLines={1}>{valorCampo}</Text>
                          </View>
                          {integranteTemNome && (
                            <Text style={[styles.statusPresenca, integranteConfirmou && styles.statusPresencaConfirmado]}>
                              {integranteConfirmou ? 'Confirmado' : 'Pendente'}
                            </Text>
                          )}
                        </>
                      ) : (
                        <>
                          <Text style={styles.valor} numberOfLines={2}>{valorCampo}</Text>
                          {integranteTemNome && (
                            <Text style={[styles.statusPresenca, integranteConfirmou && styles.statusPresencaConfirmado]}>
                              {integranteConfirmou ? 'Confirmado' : 'Pendente'}
                            </Text>
                          )}
                        </>
                      )}
                    </View>
                  ) : null}
                </View>
                {editando && campo !== 'criadoEm' ? (
                  <TextInput
                    style={styles.input}
                    value={escalaEdit[campo]}
                    onChangeText={text => handleChange(campo, text)}
                    placeholder={labelComAcento(campo)}
                    placeholderTextColor="#90caf9"
                    maxLength={campo === 'data' ? 10 : 60}
                    selectionColor="#ff9800"
                    keyboardType={campo === 'data' ? 'numeric' : 'default'}
                    textAlign="left"
                    underlineColorAndroid="transparent"
                  />
                ) : null}
              </NeumorphicContainer>
            );
          })}

          <NeumorphicContainer style={styles.uniformeBox}>
            <View style={styles.labelRow}>
              <MaterialIcons name="checkroom" size={22} color="#ff9800" style={{ marginRight: 8 }} />
              <Text style={styles.label}>Uniforme do culto</Text>
            </View>

            <View style={styles.uniformeResumoLinha}>
              <View style={styles.uniformeResumoItem}>
                <View
                  style={[
                    styles.uniformeResumoCor,
                    { backgroundColor: (editando ? escalaEdit.uniforme?.corCamiseta : escala.uniforme?.corCamiseta) || UNIFORME_PADRAO.corCamiseta },
                  ]}
                />
                <Text style={styles.uniformeResumoTexto}>Camiseta</Text>
              </View>
              <View style={styles.uniformeResumoItem}>
                <View
                  style={[
                    styles.uniformeResumoCor,
                    { backgroundColor: (editando ? escalaEdit.uniforme?.corCalcaSaia : escala.uniforme?.corCalcaSaia) || UNIFORME_PADRAO.corCalcaSaia },
                  ]}
                />
                <Text style={styles.uniformeResumoTexto}>Calça ou saia</Text>
              </View>
            </View>

            {editando && (
              <>
                <Text style={styles.uniformeLabel}>Cor da camiseta</Text>
                <View style={styles.coresLinha}>
                  {CORES_UNIFORME.map(cor => (
                    <TouchableOpacity
                      key={`edit-camiseta-${cor}`}
                      style={[
                        styles.corOpcao,
                        { backgroundColor: cor },
                        ((escalaEdit.uniforme?.corCamiseta || UNIFORME_PADRAO.corCamiseta) === cor) && styles.corOpcaoSelecionada,
                      ]}
                      onPress={() => alterarCorUniforme('corCamiseta', cor)}
                      activeOpacity={0.8}
                    />
                  ))}
                </View>

                <Text style={styles.uniformeLabel}>Cor da calça ou saia</Text>
                <View style={styles.coresLinha}>
                  {CORES_UNIFORME.map(cor => (
                    <TouchableOpacity
                      key={`edit-calça-${cor}`}
                      style={[
                        styles.corOpcao,
                        { backgroundColor: cor },
                        ((escalaEdit.uniforme?.corCalcaSaia || UNIFORME_PADRAO.corCalcaSaia) === cor) && styles.corOpcaoSelecionada,
                      ]}
                      onPress={() => alterarCorUniforme('corCalcaSaia', cor)}
                      activeOpacity={0.8}
                    />
                  ))}
                </View>
              </>
            )}
          </NeumorphicContainer>

          {permitido && (
            <View style={styles.acoesAdminNeumorphic}>
              {!editando ? (
                <>
                  <Animated.View style={{ flex: 1, marginRight: 10, transform: [{ scale: animBtn1 }] }}>
                    <TouchableOpacity
                      style={styles.saveButton}
                      onPress={() => {
                        setEscalaEdit((prev: any) => ({
                          ...prev,
                          uniforme: {
                            ...UNIFORME_PADRAO,
                            ...(escala.uniforme || {}),
                            ...(prev.uniforme || {}),
                          },
                        }));
                        setEditando(true);
                      }}
                      onPressIn={() => handlePressIn(animBtn1)}
                      onPressOut={() => handlePressOut(animBtn1)}
                      activeOpacity={0.85}
                    >
                      <Text style={styles.saveButtonText}>Editar</Text>
                    </TouchableOpacity>
                  </Animated.View>
                  <Animated.View style={{ flex: 1, transform: [{ scale: animBtn2 }] }}>
                    <TouchableOpacity
                      style={[styles.saveButton, styles.deleteButton]}
                      onPress={confirmarExclusao}
                      onPressIn={() => handlePressIn(animBtn2)}
                      onPressOut={() => handlePressOut(animBtn2)}
                      activeOpacity={0.85}
                    >
                      <Text style={[styles.saveButtonText, { color: '#fff' }]}>Excluir</Text>
                    </TouchableOpacity>
                  </Animated.View>
                </>
              ) : (
                <>
                  <Animated.View style={{ flex: 1, marginRight: 10, transform: [{ scale: animBtn1 }] }}>
                    <TouchableOpacity
                      style={styles.saveButton}
                      onPress={salvarAlterações}
                      onPressIn={() => handlePressIn(animBtn1)}
                      onPressOut={() => handlePressOut(animBtn1)}
                      activeOpacity={0.85}
                    >
                      <Text style={styles.saveButtonText}>Salvar</Text>
                    </TouchableOpacity>
                  </Animated.View>
                  <Animated.View style={{ flex: 1, transform: [{ scale: animBtn2 }] }}>
                    <TouchableOpacity
                      style={[styles.saveButton, styles.cancelButton]}
                      onPress={() => {
                        setEditando(false);
                        setEscalaEdit({ ...escala });
                      }}
                      onPressIn={() => handlePressIn(animBtn2)}
                      onPressOut={() => handlePressOut(animBtn2)}
                      activeOpacity={0.85}
                    >
                      <Text style={[styles.saveButtonText, styles.cancelButtonText]}>Cancelar</Text>
                    </TouchableOpacity>
                  </Animated.View>
                </>
              )}
            </View>
          )}
        </View>
      </ScrollView>
    </LinearGradient>
  );
}

